PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, email_verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE auth_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE profiles (id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, email TEXT NOT NULL, display_name TEXT NOT NULL DEFAULT '新用户', role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), disabled_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT);
CREATE TABLE projects (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL DEFAULT 'Untitled', thumbnail_path TEXT, background TEXT NOT NULL DEFAULT '#f2f2f0', version INTEGER NOT NULL DEFAULT 0, deleted_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE project_members (project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES profiles(id), role TEXT NOT NULL CHECK(role IN ('owner','editor','commenter')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(project_id,user_id));
CREATE TRIGGER project_owner AFTER INSERT ON projects BEGIN INSERT INTO project_members(project_id,user_id,role) VALUES (new.id,new.owner_id,'owner'); END;
CREATE TABLE project_invites (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, email TEXT NOT NULL COLLATE NOCASE, role TEXT NOT NULL CHECK(role IN ('editor','commenter')), token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, accepted_at TEXT, invited_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE canvas_snapshots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, project_version INTEGER NOT NULL, payload TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(project_id,project_version));
CREATE TABLE project_viewports (user_id TEXT NOT NULL REFERENCES profiles(id), project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, x REAL NOT NULL DEFAULT 0, y REAL NOT NULL DEFAULT 0, zoom REAL NOT NULL DEFAULT 1, updated_at TEXT, PRIMARY KEY(user_id,project_id));
CREATE TABLE comments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, object_id TEXT, x REAL, y REAL, body TEXT NOT NULL, color TEXT, author_id TEXT NOT NULL REFERENCES profiles(id), resolved_at TEXT, resolved_by TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT);
CREATE TABLE comment_replies (id TEXT PRIMARY KEY, comment_id TEXT NOT NULL REFERENCES comments(id) ON DELETE CASCADE, body TEXT NOT NULL, author_id TEXT NOT NULL REFERENCES profiles(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE assets (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES profiles(id), kind TEXT NOT NULL, storage_path TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size >= 0), width INTEGER, height INTEGER, duration_seconds REAL, source TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE voice_profiles (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES profiles(id), project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, project_name TEXT NOT NULL, name TEXT NOT NULL, voice_id TEXT NOT NULL, source_model TEXT NOT NULL, last_used_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT, UNIQUE(user_id,voice_id));
CREATE TABLE provider_configs (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, base_url TEXT NOT NULL, adapter TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT);
CREATE TABLE model_configs (id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES provider_configs(id), model_id TEXT NOT NULL, display_name TEXT NOT NULL, kind TEXT NOT NULL, capabilities TEXT NOT NULL DEFAULT '{}', pricing TEXT NOT NULL DEFAULT '{}', enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT, UNIQUE(provider_id,model_id));
CREATE TABLE credit_accounts (user_id TEXT PRIMARY KEY REFERENCES profiles(id), balance INTEGER NOT NULL DEFAULT 0);
CREATE TABLE credit_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES profiles(id), amount INTEGER NOT NULL, kind TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE chat_sessions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES profiles(id), title TEXT NOT NULL DEFAULT '新对话', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT);
CREATE TABLE chat_messages (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES chat_sessions(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX snapshots_project_version ON canvas_snapshots(project_id,project_version DESC);
CREATE INDEX members_user ON project_members(user_id,project_id);
CREATE INDEX comments_project ON comments(project_id);
CREATE INDEX assets_project ON assets(project_id);
